using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using Sunplus.Core.Common;
using Sunplus.Shared.ViewLogLib.DataAccess;
using Sunplus.Shared.ViewLogLib.Entities;
using Sunplus.Agent.Model.Entities;

namespace Sunplus.Shared.ViewLogLib.Services
{
    public class LogService<T> : ILogService<T> where T : LogBase 
    {
        private readonly ILogRepository<T> _logRepository;

        public LogService()
        {
            _logRepository = new LogRepository<T>();
        }
       
        public LogService(ILogRepository<T> logRepository)
        {
            _logRepository = logRepository;
        }

        #region ILogService<T> Members

        /// <summary>
        /// 
        /// </summary>
        /// <param name="context"><see cref="IRequestViewLogContext"/></param>
        /// <param name="pageIndex"></param>
        /// <param name="pageSize"></param>
        /// <param name="totalRecords"></param>
        /// <returns></returns>
        public List<T> GetPaged(IRequestViewLogContext context
            , int pageIndex, int pageSize, out int totalRecords, IList<IExtObject<string, string>> permissions, Dictionary<string, string> p2pStakes = null)
        {
            var entityList = new List<T>();
            totalRecords = 0;

            entityList = _logRepository.GetPaged(context, pageIndex, pageSize, out totalRecords);

            bool isShowOldValue = context.ShowOldValue;
            LanguageCode languageCode = context.LanguageCode;

            LogActionService logActionService = new LogActionService();

            foreach (T entity in entityList)
            {
                LogBase log = entity as LogBase;
                // Format log action language
                log.ActionName = logActionService.GetLogActionName(log.ActionID, languageCode);

                if (log is LogRunSp)
                { // Format tracking value
                    LogRunSp logRunSp = log as LogRunSp;
                    logRunSp.TrackingValue = Utility.XmlDiff(logRunSp.TrackingValueOld, logRunSp.TrackingValue, isShowOldValue, permissions, log.ActionID >= 351 && log.ActionID <= 354, p2pStakes);
                }
            }

            return entityList;
        }

        #endregion
    }
}
